  function walk(node, depth) {
    if (depth < 3) {
      let extra = '';
      if (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET') {
        extra = ' key=' + node.key;
      }
      if (node.type === 'INSTANCE') {
        if (node.mainComponent) extra = ' main=' + node.mainComponent.name + ' mainId=' + node.mainComponent.id;
      }
      out.push('  '.repeat(depth) + node.type + ' ' + node.name + ' id=' + node.id + ' x=' + node.x + ' y=' + node.y + ' w=' + node.width + ' h=' + node.height + extra);
