async function run() {
  // Load Poppins fonts
  const fonts = ['Regular','Medium','SemiBold','Bold'];
  for (const f of fonts){ await figma.loadFontAsync({family:'Poppins', style:f}); }
  // find workspace page
  const ws = figma.root.children.find(p=>p.name.indexOf('03')===0);
  await figma.setCurrentPageAsync(ws);
  // create 12 frames
  const names = ['01_Splash','02_Onboarding','03_Sign_In','04_Verification','05_Home','06_Product_Detail','07_Explore','08_Beverages','09_My_Cart','10_Checkout_Overlay','11_Order_Accepted','12_Account'];
  const frames = {};
  for (let i=0;i<names.length;i++){
    const f = figma.createFrame();
    f.name = names[i];
    f.resize(414, 896);
    f.x = 40 + (i%3)*460;
    f.y = 40 + Math.floor(i/3)*940;
    f.fills = [{type:'SOLID', color:{r:0.98,g:0.99,b:0.985}}];
    f.clipsContent = true;
    ws.appendChild(f);
    frames[names[i]] = f.id;
  }
  let r = 'FRAMES:';
  for (const k in frames) r+='\n'+k+'='+frames[k];
  r+='\nPAGE='+ws.id;
  return r;
}
