async function run(){
  const ws = figma.root.children.find(p=>p.name.indexOf('03')===0);
  const F = n=>ws.children.find(f=>f.name===n);
  const ids = {};
  ['01_Splash','02_Onboarding','03_Sign_In','04_Verification','05_Home','06_Product_Detail','07_Explore','08_Beverages','09_My_Cart','10_Checkout_Overlay','11_Order_Accepted','12_Account'].forEach(n=>ids[n]=F(n).id);

  function addReaction(node, triggerType, destinationId, navigation){
    const trigger = triggerType==='AFTER_TIMEOUT' ? { type:'AFTER_TIMEOUT', timeout:2000 } : { type:'ON_CLICK' };
    node.reactions = [{
      action:{ type:'NODE', destinationId, navigation: navigation||'NAVIGATE', transition:{type:'SMART_ANIMATE',duration:300,easing:'EASE_IN_OUT'} },
      trigger
    }];
  }

  // 01 Splash -> auto 02
  addReaction(F('01_Splash'),'AFTER_TIMEOUT',ids['02_Onboarding']);

  // 02 Get Started -> 03 (the button instance)
  const ob = F('02_Onboarding');
  const obBtn = ob.findAll(n=>n.type==='INSTANCE'&&n.name==='Get Started')[0];
  if(obBtn) addReaction(obBtn,'ON_CLICK',ids['03_Sign_In']);

  // 03 phone number -> 04. Make phone underline/flag clickable -> create hidden area. Simpler: use heading? Put on Phone frame.
  const si = F('03_Sign_In');
  const siPhone = si.children.find(n=>n.name==='Phone');
  if(siPhone) addReaction(siPhone,'ON_CLICK',ids['04_Verification']);

  // 04 verification back -> 03, next -> 05
  const vf = F('04_Verification');
  const vfBack = vf.children.find(n=>n.type==='TEXT'&&n.characters==='←');
  if(vfBack) addReaction(vfBack,'ON_CLICK',ids['03_Sign_In']);
  const vfNext = vf.findAll(n=>n.type==='INSTANCE'&&n.name==='Button')[0];
  if(vfNext) addReaction(vfNext,'ON_CLICK',ids['05_Home']);

  // 05 Home: Red Apple card -> 06. Which product card is "Red Apple"? second product in Exclusive Offer (index col2). Create an invisible click through naming. We'll attach reaction on the Red Apple card.
  // Simplest: create overlay rectangle over Red Apple card and attach.
  const home = F('05_Home');
  const redAppleRect = figma.createRectangle(); redAppleRect.resize(165,190); redAppleRect.x=219; redAppleRect.y=414; redAppleRect.fills=[{type:'SOLID',color:{r:0, g:0, b:0}, opacity:0}]; home.appendChild(redAppleRect);
  addReaction(redAppleRect,'ON_CLICK',ids['06_Product_Detail']);

  // 06 Add To Basket -> 09, back -> 05
  const pd = F('06_Product_Detail');
  const pdBtn = pd.findAll(n=>n.type==='INSTANCE'&&n.name==='Button')[0];
  if(pdBtn) addReaction(pdBtn,'ON_CLICK',ids['09_My_Cart']);
  const pdBack = pd.children.find(n=>n.type==='TEXT'&&n.characters==='←');
  if(pdBack) addReaction(pdBack,'ON_CLICK',ids['05_Home']);

  // 07 Explore: Beverages category -> 08. bottles category is last (index5) at row2 col1.
  const ex = F('07_Explore');
  const bevRect = figma.createRectangle(); bevRect.resize(184,160); bevRect.x=212; bevRect.y=540; bevRect.fills=[{type:'SOLID',color:{r:0,g:0,b:0},opacity:0}]; ex.appendChild(bevRect);
  addReaction(bevRect,'ON_CLICK',ids['08_Beverages']);

  // 08 back -> 07
  const bv = F('08_Beverages');
  const bvBack = bv.children.find(n=>n.type==='TEXT'&&n.characters==='←');
  if(bvBack) addReaction(bvBack,'ON_CLICK',ids['07_Explore']);

  // 09 Go to Checkout -> 10
  const cart = F('09_My_Cart');
  const chkBtn = cart.findAll(n=>n.type==='INSTANCE'&&n.name==='Button')[0];
  // Identify: there are multiple? only one button
  if(chkBtn) addReaction(chkBtn,'ON_CLICK',ids['10_Checkout_Overlay'],'OVERLAY');
  // Actually overlay opens over cart; use NAVIGATE with overlay. Use transition overlay.
  // Use action navigation 'OVERLAY' for overlay.

  // 10 close -> 09, Place Order -> 11
  const co = F('10_Checkout_Overlay');
  const coClose = co.children.find(n=>n.type==='TEXT'&&n.characters==='x');
  if(coClose) addReaction(coClose,'ON_CLICK',ids['09_My_Cart']);
  const coBtn = co.findAll(n=>n.type==='INSTANCE'&&n.name==='Button')[0];
  if(coBtn) addReaction(coBtn,'ON_CLICK',ids['11_Order_Accepted']);

  // 11 Back to home -> 05
  const oa = F('11_Order_Accepted');
  const oaBack = oa.children.find(n=>n.type==='TEXT'&&(n.characters==='Back to home'));
  if(oaBack) addReaction(oaBack,'ON_CLICK',ids['05_Home']);

  return 'Reactions wired. Splash reactions='+F('01_Splash').reactions.length;
}
return run().then(r=>r);
